import { type MouseEvent as ReactMouseEvent, useEffect, useRef } from "react";
import { type CalendarId, type EventId } from "@core/types/domain-primitives";
import { type Dayjs } from "@core/util/date/dayjs";
import { createObjectIdString } from "@web/common/utils/id/object-id.util";
import { type GridEventDraft } from "@web/events/event-draft.types";
import {
  createGridEventDraft,
  replaceGridDraftSchedule,
  timedGridSchedule,
} from "@web/events/grid-event-draft.adapter";
import {
  draftActions,
  selectIsDrafting,
  useDraftStore,
} from "@web/events/stores/draft.store";
import { DRAFT_DURATION_MIN, GRID_TIME_STEP } from "@web/grid/grid.constants";
import { TIMED_DRAFT_CREATE_MOVE_THRESHOLD_PX } from "@web/interaction/interaction.constants";
import {
  hasExceededInteractionMoveThreshold,
  isEligibleInteractionPointerDown,
} from "@web/interaction/interaction.pointer";

interface TimedDraftCreationGesture {
  cancel(): void;
}

interface UseTimedDraftCreationOptions {
  calendarId?: CalendarId | null;
  finishWhenPrimaryButtonReleased?: boolean;
  getStartDate: (point: { x: number; y: number }) => Dayjs;
  onFinish: (draft: GridEventDraft) => void;
}

export const useTimedDraftCreation = ({
  calendarId = null,
  finishWhenPrimaryButtonReleased = true,
  getStartDate,
  onFinish,
}: UseTimedDraftCreationOptions) => {
  const isDrafting = useDraftStore(selectIsDrafting);
  const gestureRef = useRef<TimedDraftCreationGesture | null>(null);

  useEffect(() => {
    return () => {
      gestureRef.current?.cancel();
    };
  }, []);

  const startTimedDraftCreation = (
    event: ReactMouseEvent<HTMLElement>,
    columnCalendarId: CalendarId | null = calendarId,
  ) => {
    if (isDrafting) {
      draftActions.discard();
      return;
    }

    if (
      !isEligibleInteractionPointerDown({
        altKey: event.altKey,
        button: event.button,
        ctrlKey: event.ctrlKey,
        isPrimary: true,
        metaKey: event.metaKey,
        shiftKey: event.shiftKey,
      })
    ) {
      return;
    }

    event.preventDefault();
    event.stopPropagation();
    gestureRef.current?.cancel();

    const pointerStart = getPointerPoint(event);
    const start = getStartDate(pointerStart);
    const draftEvent = createGridEventDraft(
      timedGridSchedule(
        start.toDate(),
        start.add(DRAFT_DURATION_MIN, "minutes").toDate(),
      ),
      createObjectIdString() as EventId,
      columnCalendarId,
    );
    let hasMoved = false;
    let isCancelled = false;
    let isFinished = false;
    let isPreviewStarted = false;

    const resolveDraftForPointer = (point: { x: number; y: number }) => {
      // Clicks keep the 30-minute default. Once the pointer has moved, the end
      // can shrink to one grid step (15) without flipping past the origin.
      const defaultEndDate = start.add(DRAFT_DURATION_MIN, "minutes");

      if (!hasMoved) {
        return replaceGridDraftSchedule(
          draftEvent,
          timedGridSchedule(start.toDate(), defaultEndDate.toDate()),
        );
      }

      const minimumEndDate = start.add(GRID_TIME_STEP, "minutes");
      const pointerDate = getStartDate(point);
      const isSameDayDrag = pointerDate.isSame(start, "day");
      const isUpwardDrag = isSameDayDrag && pointerDate.isBefore(start);

      let resolvedStartDate = start;
      let resolvedEndDate = defaultEndDate;

      if (isUpwardDrag) {
        resolvedStartDate = pointerDate;
        resolvedEndDate = start;
      } else if (isSameDayDrag) {
        resolvedEndDate = pointerDate.isBefore(minimumEndDate)
          ? minimumEndDate
          : pointerDate;
      }

      return replaceGridDraftSchedule(
        draftEvent,
        timedGridSchedule(resolvedStartDate.toDate(), resolvedEndDate.toDate()),
      );
    };

    const cleanup = () => {
      window.removeEventListener("mousemove", handleMouseMove, true);
      window.removeEventListener("mouseup", handleMouseUp, true);
      window.removeEventListener("blur", handleWindowBlur);
      gestureRef.current = null;
    };

    const openTimedDraft = (mouseEvent: MouseEvent) => {
      const nextDraft = resolveDraftForPointer(getPointerPoint(mouseEvent));
      if (isCancelled) {
        return;
      }

      onFinish(nextDraft);
    };

    // The store draft is the preview: both views render it straight from the
    // store while the gesture runs, so every move has to write it.
    const previewDraft = (mouseEvent: MouseEvent) => {
      const nextDraft = resolveDraftForPointer(getPointerPoint(mouseEvent));
      if (isCancelled || isFinished) {
        return;
      }

      if (isPreviewStarted) {
        draftActions.setGridDraft(nextDraft);
        return;
      }

      isPreviewStarted = true;
      draftActions.startGridDraft({ activity: "creating", draft: nextDraft });
    };

    function finish(mouseEvent: MouseEvent) {
      if (isFinished || isCancelled) {
        return;
      }

      isFinished = true;
      cleanup();
      mouseEvent.preventDefault();
      mouseEvent.stopPropagation();
      openTimedDraft(mouseEvent);
    }

    function cancel() {
      if (isFinished || isCancelled) {
        return;
      }

      isCancelled = true;
      cleanup();

      if (isPreviewStarted) {
        draftActions.discard();
      }
    }

    function handleMouseMove(mouseEvent: MouseEvent) {
      if (isFinished || isCancelled) {
        return;
      }

      if (mouseEvent.buttons !== 1) {
        if (finishWhenPrimaryButtonReleased) {
          finish(mouseEvent);
        }
        return;
      }

      if (
        !hasMoved &&
        !hasExceededInteractionMoveThreshold(
          getPointerPoint(mouseEvent),
          pointerStart,
          TIMED_DRAFT_CREATE_MOVE_THRESHOLD_PX,
        )
      ) {
        return;
      }

      hasMoved = true;
      previewDraft(mouseEvent);
    }

    function handleMouseUp(mouseEvent: MouseEvent) {
      finish(mouseEvent);
    }

    function handleWindowBlur() {
      cancel();
    }

    window.addEventListener("mousemove", handleMouseMove, true);
    window.addEventListener("mouseup", handleMouseUp, true);
    window.addEventListener("blur", handleWindowBlur);
    gestureRef.current = { cancel };
  };

  return {
    startTimedDraftCreation,
  };
};

const getPointerPoint = ({
  clientX,
  clientY,
}: {
  clientX: number;
  clientY: number;
}) => ({
  x: clientX,
  y: clientY,
});

import { type InteractionPoint } from "./interaction.types";

export interface InteractionPointerEligibilityInput {
  altKey: boolean;
  button: number;
  ctrlKey: boolean;
  isPrimary: boolean;
  metaKey: boolean;
  shiftKey: boolean;
}

export const isEligibleInteractionPointerDown = ({
  altKey,
  button,
  ctrlKey,
  isPrimary,
  metaKey,
  shiftKey,
}: InteractionPointerEligibilityInput) =>
  isPrimary !== false &&
  button === 0 &&
  !altKey &&
  !ctrlKey &&
  !metaKey &&
  !shiftKey;

export const hasExceededInteractionMoveThreshold = (
  current: InteractionPoint,
  initial: InteractionPoint,
  threshold: number,
) =>
  Math.abs(current.x - initial.x) > threshold ||
  Math.abs(current.y - initial.y) > threshold;

import {
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react";
import { useEffect } from "react";
import { type GridEventDraft } from "@web/events/event-draft.types";
import { createGridEventDraft } from "@web/events/grid-event-draft.adapter";
import { draftActions, useDraftStore } from "@web/events/stores/draft.store";
import { useAllDayDraftCreation } from "./useAllDayDraftCreation";
import { afterEach, describe, expect, it, mock } from "bun:test";

const existingDraft = createGridEventDraft({
  kind: "allDay",
  start: new Date("2026-05-20"),
  end: new Date("2026-05-21"),
});

const renderHarness = ({
  draft = null,
  onCreateGridDraft = mock(),
  onParentMouseDown = mock(),
}: {
  draft?: GridEventDraft | null;
  onCreateGridDraft?: (draft: GridEventDraft) => void;
  onParentMouseDown?: () => void;
} = {}) => {
  if (draft) {
    draftActions.startGridDraft({ activity: "gridClick", draft });
  }

  const Harness = () => {
    const onMouseDown = useAllDayDraftCreation({
      getStartDate: () => "2026-05-20",
      onCreateGridDraft,
    });

    useEffect(() => {
      document.addEventListener("mousedown", onParentMouseDown);
      return () => document.removeEventListener("mousedown", onParentMouseDown);
    }, []);

    return (
      <button onMouseDown={onMouseDown} type="button">
        Empty all-day space
      </button>
    );
  };

  render(<Harness />);

  return { onCreateGridDraft, onParentMouseDown };
};

afterEach(cleanup);

describe("useAllDayDraftCreation", () => {
  it("creates a one-day all-day draft and stops the opening press", async () => {
    const { onCreateGridDraft, onParentMouseDown } = renderHarness();

    const wasNotCancelled = fireEvent.mouseDown(
      screen.getByRole("button", { name: "Empty all-day space" }),
      { button: 0 },
    );

    expect(wasNotCancelled).toBe(false);
    expect(onParentMouseDown).not.toHaveBeenCalled();
    await waitFor(() => expect(onCreateGridDraft).toHaveBeenCalledTimes(1));
    expect(onCreateGridDraft).toHaveBeenCalledWith(
      expect.objectContaining({
        values: expect.objectContaining({
          schedule: {
            end: new Date("2026-05-21"),
            kind: "allDay",
            start: new Date("2026-05-20"),
          },
        }),
      }),
    );
  });

  it("ignores right-click presses", () => {
    const { onCreateGridDraft, onParentMouseDown } = renderHarness();

    fireEvent.mouseDown(
      screen.getByRole("button", { name: "Empty all-day space" }),
      { button: 2 },
    );

    expect(onCreateGridDraft).not.toHaveBeenCalled();
    expect(onParentMouseDown).toHaveBeenCalledTimes(1);
  });

  it("dismisses an existing draft without creating a replacement", async () => {
    const { onCreateGridDraft, onParentMouseDown } = renderHarness({
      draft: existingDraft,
    });

    fireEvent.mouseDown(
      screen.getByRole("button", { name: "Empty all-day space" }),
      { button: 0 },
    );

    await waitFor(() => expect(useDraftStore.getState().gridDraft).toBeNull());
    expect(onCreateGridDraft).not.toHaveBeenCalled();
    expect(onParentMouseDown).not.toHaveBeenCalled();
  });
});

